import{_ as i,C as a,o as h,c as d,j as t,a as n,E as s,a6 as p}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse('{"title":"Piwi Runner","description":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray.","frontmatter":{"title":"Piwi Runner","description":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/piwi-runner.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/piwi-runner.html"}],["meta",{"property":"og:title","content":"Piwi Runner | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray."}]]},"headers":[],"relativePath":"features/piwi-runner.md","filePath":"features/piwi-runner.md","lastUpdated":1794655428000}'),l={name:"features/piwi-runner.md"};function c(u,e,w,g,m,f){const o=a("Needs"),r=a("DownloadApps");return h(),d("div",null,[e[0]||(e[0]=t("h1",{id:"piwi-runner",tabindex:"-1"},[n("Piwi Runner "),t("a",{class:"header-anchor",href:"#piwi-runner","aria-label":'Permalink to "Piwi Runner"'},"​")],-1)),s(o,{admin:""}),e[1]||(e[1]=t("p",null,[n("Piwi Runner takes "),t("a",{href:"./run-on-my-machine.html"},"Run on my machine"),n(" requests from one team instance, without the dashboard: one window for the connection, the confirmation of each request and the runs it started. It is for a machine that only runs what the instance asks, where the "),t("a",{href:"./desktop.html"},"desktop app"),n(" and its local dashboard are more than needed. It keeps no database and serves no dashboard.")],-1)),e[2]||(e[2]=t("h2",{id:"where-it-is",tabindex:"-1"},[n("Where it is "),t("a",{class:"header-anchor",href:"#where-it-is","aria-label":'Permalink to "Where it is"'},"​")],-1)),s(r,{app:"runner"}),e[3]||(e[3]=p('<p>What each installer needs:</p><table tabindex="0"><thead><tr><th>OS</th><th>Installer</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td><code>.exe</code> (per-user, no admin) or <code>.msi</code> (per-machine)</td></tr><tr><td><strong>macOS</strong> 13.5+ (Apple silicon)</td><td><code>.dmg</code></td></tr><tr><td><strong>Linux</strong> (x86-64)</td><td><code>.AppImage</code>, <code>.deb</code> or <code>.rpm</code>, each needing a system WebKitGTK (<code>webkit2gtk-4.1</code>)</td></tr></tbody></table><p>The installers are <strong>unsigned</strong>: on macOS, open the app once, then <strong>Open Anyway</strong> in <strong>Privacy &amp; Security</strong>; on Windows, <strong>More info</strong> then <strong>Run anyway</strong> in SmartScreen.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Piwi Runner checks the latest release when it starts, and a notification says when a newer version is out. <strong>Check for updates…</strong> in the tray menu checks again; when one is found, <strong>Install and restart</strong> downloads it, checks its signature, installs it the way it was installed (<code>.exe</code>, <code>.msi</code>, <code>.dmg</code>, <code>.AppImage</code>, <code>.deb</code> or <code>.rpm</code>) and starts the new version, after asking to stop the runs still going. Your connection and linked folders stay. A new release&#39;s Piwi Runner files can reach the release a few minutes after the desktop app&#39;s; until then the check finds nothing new or fails, and the next one finds them. On a desktop that shows no tray icon, install a new version from the latest release over the old one.</p><h2 id="piwi-runner-or-the-desktop-app" tabindex="-1">Piwi Runner or the desktop app <a class="header-anchor" href="#piwi-runner-or-the-desktop-app" aria-label="Permalink to &quot;Piwi Runner or the desktop app&quot;">​</a></h2><p>You need one of the two, not both. The desktop app takes the same requests, with the same confirmation and checks, and adds the dashboard on your machine and a requested run you can pause, step and watch live from its window, where Piwi Runner shows the run&#39;s output and <strong>Stop</strong>. Piwi Runner is for a machine that only runs what the instance asks.</p><p>Installed together, they live side by side, and neither installer replaces the other: each has its own name, install folder, Linux package, settings, linked folders and keychain entry. Connected to the same instance, both are listed in <strong>Connected apps</strong>, and a request goes to the one you pick on the page.</p><h2 id="connect-it" tabindex="-1">Connect it <a class="header-anchor" href="#connect-it" aria-label="Permalink to &quot;Connect it&quot;">​</a></h2><p>Its window connects to an instance the way the desktop app does: enter the instance&#39;s address and click <strong>Connect</strong>, then allow <strong>Piwi Runner</strong> on the instance&#39;s page with the code the window shows. Its key stays in the operating system&#39;s keychain. Each project&#39;s folder is linked on the first request for it. The rest, from the confirmation to <strong>Stop</strong>, is described in <a href="./run-on-my-machine.html#in-the-app">Run on my machine</a>.</p><h2 id="pause-and-watch-a-run" tabindex="-1">Pause and watch a run <a class="header-anchor" href="#pause-and-watch-a-run" aria-label="Permalink to &quot;Pause and watch a run&quot;">​</a></h2><p>Each run Piwi Runner starts shows in its window live, as the desktop app&#39;s runs show in its <a href="./desktop-runs.html">Local runs tray</a>: each worker&#39;s test and where it stands, <strong>Pause</strong>, <strong>Step</strong>, <strong>Resume</strong> and <strong>Finish</strong>, <strong>Pause all</strong> and <strong>Resume all</strong>, and the stopped test&#39;s page, live with <strong>Watch</strong>. A <code>page.pause()</code>, a step or a breakpoint waits in the window until you answer it, and the window comes to the front. <strong>Hold failures</strong>, on each running run you attend and off until you turn it on, keeps a failing test at its line too, until you resume it; a run in UI mode, or one that repeats its tests past a failure, offers none. Once the run reported to the instance, its card names it, <strong>Run #78 · Open</strong>, which opens its page there, and keeps it after the run ended. A run that goes on while the window reloads shows again, with <strong>Stop</strong>. <strong>Assert a region</strong> and <strong>Mock a request</strong> make their code in the window, to copy: Piwi Runner has no editor and writes no file. <strong>Share live</strong> shows the run&#39;s stops to your team on the instance it reports to, as in the desktop app. <strong>Inspect</strong> of a watched worker, which reads the test&#39;s pages from its trace, is the desktop app&#39;s alone.</p><p>Piwi Runner is the hub of its own runs only: Piwi Picker, the editors and an agent reach the runs the desktop app or an editor starts, not Piwi Runner&#39;s.</p><h2 id="in-the-tray" tabindex="-1">In the tray <a class="header-anchor" href="#in-the-tray" aria-label="Permalink to &quot;In the tray&quot;">​</a></h2><p>Closing the window leaves Piwi Runner in the tray, still connected, so the instance can reach it; a request brings the window forward. The tray menu has:</p><ul><li><strong>Open Piwi Runner</strong> (on Windows and macOS, a click on the icon does the same) and <strong>Show logs</strong>;</li><li><strong>Run in background</strong>, on by default: turned off, closing the window quits the app, once you agree to stop the runs still going;</li><li><strong>Start on login</strong>, which launches it in the tray when you sign in;</li><li><strong>Check for updates…</strong>;</li><li><strong>Quit Piwi Runner</strong>, which stops its runs, after asking.</li></ul><p>The window has the same two settings, for a desktop that shows no tray icon (GNOME without an AppIndicator extension): turn <strong>Keep running in the tray when the window closes</strong> off there, and closing the window quits.</p><p>Its icon is the Piwi mark on a teal tile with a play sign, so it reads apart from the desktop app&#39;s in the tray and the taskbar.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./run-on-my-machine.html">Run on my machine</a>: who may ask, how an administrator turns it on, and what a request holds</li><li><a href="./desktop.html">Desktop app</a>: the other app that takes requests, with a local dashboard</li></ul>',20))])}const b=i(l,[["render",c]]);export{y as __pageData,b as default};
